def fill_work_groups(apps, schema_editor):
    """ADR 0052 Q4: a case takes the กลุ่มงาน of the unit card it matched, when that กลุ่มงาน
    sits in the case's แผนก."""
    Case = apps.get_model("operations", "Case")
    for case in Case.objects.filter(
        work_group__isnull=True, unit_work__work_group__isnull=False
    ).select_related("unit_work__work_group"):
        group = case.unit_work.work_group
        if group.section_id == case.section_id:
            Case.objects.filter(pk=case.pk).update(work_group=group)


